//! ↩️ reorder-samplers leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSampler;
use crate::artifacts::gltf::schema::mutations::reorder_samplers::mutation::{validate, GltfReorderSamplersPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{samplers_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-samplers.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderSamplersInverseOperation { Insert { position: usize, item: GltfSampler }, Delete { index: usize, removed: GltfSampler }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderSamplersInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderSamplersPayload, pub operation: GltfReorderSamplersInverseOperation }
fn operation(payload: &GltfReorderSamplersPayload, base: &GltfSnapshot) -> GltfReorderSamplersInverseOperation { GltfReorderSamplersInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
fn touched_paths(payload: &GltfReorderSamplersPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/samplers/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_inverse(inverse: &GltfReorderSamplersInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfReorderSamplersInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderSamplersInverseOperation::Insert { position, .. } if *position > after.document.samplers.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/samplers", "position must be within the collection")), GltfReorderSamplersInverseOperation::Delete { index, .. } if *index >= after.document.samplers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/samplers", "index must address an item")), GltfReorderSamplersInverseOperation::Move { index, position } if *index >= after.document.samplers.len() || *position >= after.document.samplers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/samplers", "indices must address items")), GltfReorderSamplersInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.samplers.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.samplers.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/samplers", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderSamplersInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Samplers, &Change::Insert(*position))?; next.document.samplers.insert(*position, item.clone());  }, GltfReorderSamplersInverseOperation::Delete { index, .. } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, None, None)?;  }, GltfReorderSamplersInverseOperation::Move { index, position } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, Some(*position), None)?;  }, GltfReorderSamplersInverseOperation::Reorder { order } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfReorderSamplersInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfReorderSamplersPayload, base: &GltfSnapshot) -> Result<GltfReorderSamplersInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderSamplersInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
